package com.primehr.rsp.evaluation;
import com.primehr.rsp.evaluation.api.EvaluationPolicyDtos.*; import com.primehr.rsp.evaluation.application.*; import com.primehr.rsp.evaluation.domain.*; import com.primehr.shared.exception.*; import org.junit.jupiter.api.*; import org.springframework.beans.factory.annotation.*; import org.springframework.boot.test.context.*; import org.springframework.test.context.*; import org.springframework.transaction.annotation.*; import java.math.*; import java.time.*; import java.util.*; import static org.assertj.core.api.Assertions.*;
@SpringBootTest @ActiveProfiles("test") @Transactional class EvaluationPolicyServiceIntegrationTest {@Autowired EvaluationPolicyService service;
 @Test void policyIsTransparentVersionedImmutableAndNonOverlapping(){PolicyResponse draft=service.create("TEST-AGENCY",request("MSP",null),"create");assertThat(draft.stages()).hasSize(2);PolicyResponse published=service.publish("TEST-AGENCY",draft.id(),new Publish(draft.recordVersion(),LocalDate.of(2026,1,1),null),"publish");assertThat(published.status()).isEqualTo("PUBLISHED");assertThatThrownBy(()->service.update("TEST-AGENCY",draft.id(),request("MSP",published.recordVersion()),null)).hasMessageContaining("immutable");PolicyResponse next=service.successor("TEST-AGENCY",draft.id(),new Transition(published.recordVersion()),null);PolicyResponse nextPublished=service.publish("TEST-AGENCY",next.id(),new Publish(next.recordVersion(),LocalDate.of(2027,1,1),null),null);assertThat(nextPublished.definitionVersion()).isEqualTo(2);assertThat(service.get("TEST-AGENCY",draft.id()).effectiveTo()).isEqualTo(LocalDate.of(2026,12,31));}
 @Test void invalidWeightsDuplicatesAndStaleWritesFailWithoutMutation(){SavePolicy bad=new SavePolicy("BAD","Bad",null,"MSP",2,EvaluationPolicy.Rounding.HALF_UP,EvaluationPolicy.TieRule.COMPETITION,List.of(stage("A",0,new BigDecimal("60")),stage("B",1,new BigDecimal("30"))),null);assertThatThrownBy(()->service.create("TEST-AGENCY",bad,null)).hasMessageContaining("total 100");StageInput duplicate=stage("A",0,new BigDecimal("100"));SavePolicy duplicates=new SavePolicy("DUP","Duplicate",null,"MSP",2,EvaluationPolicy.Rounding.HALF_UP,EvaluationPolicy.TieRule.DENSE,List.of(duplicate,duplicate),null);assertThatThrownBy(()->service.create("TEST-AGENCY",duplicates,null)).hasMessageContaining("Duplicate");PolicyResponse draft=service.create("TEST-AGENCY",request("STALE",null),null);assertThatThrownBy(()->service.update("TEST-AGENCY",draft.id(),request("STALE",99L),null)).isInstanceOf(OptimisticConflictException.class);}
 private static SavePolicy request(String code,Long version){return new SavePolicy(code,"Policy "+code,"Generic","Agency MSP 2026",2,EvaluationPolicy.Rounding.HALF_UP,EvaluationPolicy.TieRule.COMPETITION,List.of(stage("EXAM",0,new BigDecimal("60")),stage("BEI",1,new BigDecimal("40"))),version);}private static StageInput stage(String code,int order,BigDecimal weight){return new StageInput(code,code,null,code.equals("BEI")?EvaluationStage.Type.BEHAVIORAL_EVENT_INTERVIEW:EvaluationStage.Type.WRITTEN_EXAMINATION,EvaluationStage.Mode.SCORED,weight,new BigDecimal("100"),new BigDecimal("50"),1,true,order,List.of(new CriterionInput("TOTAL","Total",null,new BigDecimal("100"),new BigDecimal("100"),false,0)));}}
